declarations.original_declaration:
process ChoiceMaking
    "Intentional activity of considering alternatives in forming a choice."
    is agency:Intentional physical:Activity;

process Negotiation
    "Activity in which agents seek an agreement through interaction."
    is physical:Activity;

process CollectiveCoordination
    "Activity through which agents coordinate their actions."
    is physical:Activity;

abstract functional relationship AgentInteraction
    "Dynamic interaction involving an agent as source and a substantial as target."
    links imod:Agent to (imod:Agent or imod:Subject);

structural directed relationship Represents
    "An agent has a recognized mandate to act for another agent in a stated scope."
    links imod:Agent to imod:Agent;
